layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(245, 242, 235); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 15.2px; padding-right: 19px; padding-bottom: 15.2px; padding-left: 19px; transition: all }
[data-ryt="footer"] { color: var(--ryt-muted); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px dotted var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: border-color 0.2s, color 0.2s, background 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(22, 22, 14); font-family: var(--ryt-font-heading); font-size: 28px; font-weight: 700; font-style: normal; line-height: 1.35; letter-spacing: -0.28px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(22, 22, 14); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(22, 22, 14); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.35; letter-spacing: -0.28px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(22, 22, 14); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(22, 22, 14); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.7; letter-spacing: 0.32px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(22, 22, 14); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgba(0, 0, 0, 0.1); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-muted); border-radius: 6px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: color 0.2s, background 0.2s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.2s }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(22, 22, 14); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: -0.28px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(22, 22, 14); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(22, 22, 14); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28px; font-weight: 700; font-style: normal; line-height: 1.35; letter-spacing: -0.28px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(22, 22, 14); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: #9E3D3F }
